/// <reference types="vite/client" />

declare module '*.css' {
  const content: string
  export default content
}

// Generated by the cafs-git-stamps plugin in vite.config.ts: for each content
// file, the git author date of the commit that last touched every line
// (ISO string, or '' when the line has no history). Indices are 0-based line
// numbers of the markdown file.
declare module 'virtual:cafs-git-stamps' {
  const stamps: Record<string, string[]>
  export default stamps
}
